import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"你的世界，不止一种玩法","description":"","frontmatter":{"layout":"home","title":"你的世界，不止一种玩法","hero":{"name":"PotgCraft","text":"你的世界，不止一种玩法","tagline":"有人喜欢盖房子，有人热衷红石，也有人能对着机器和管道折腾一整晚。在增强生存与科技空岛，找到你愿意慢慢经营的世界。","actions":[{"theme":"brand","text":"选择你的玩法","link":"/#worlds"},{"theme":"alt","text":"查找玩法攻略","link":"/guides/"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<section class="portal-section" aria-labelledby="worlds"><p class="section-kicker">一个品牌 · 两个子服</p><h2 id="worlds">今天，想在哪个世界开工？</h2><p class="section-lead">想在地表安个家，还是从空岛起步？先看看两边的玩法和客户端要求。</p><div class="portal-grid worlds-grid"><a class="portal-card world-card" href="/server-intro.html"><span class="card-eyebrow">增强生存 · 原版方向</span><h3>熟悉的世界，更多的可能</h3><p>找一块喜欢的地方盖房子，和朋友研究红石与生电工程。特殊配方、便携工具，还有云层之上的天堂维度，为日常生存添一点新鲜感。</p><div class="card-tags"><span>建筑</span><span>红石生电</span><span>轻量定制</span><span>长期建设</span></div><p class="card-meta">当前 Leaf 26.2 · 原版客户端可加入，兼容版本请先查看说明</p><span class="card-link">了解增强生存与加入方式 →</span></a><a class="portal-card world-card" href="/skyblock/"><span class="card-eyebrow">科技空岛 · 模组玩法</span><h3>从一座空岛，到一座自动化工厂</h3><p>把鱼竿抛向虚空，带回第一批材料与种源。推进岛屿任务、发展产矿，再把机器、能源和仓储连起来，让基地按照你的设计运转。</p><div class="card-tags"><span>漂流钓鱼</span><span>岛屿成长</span><span>科技自动化</span><span>多人合作</span></div><p class="card-meta">Java 1.21.1 · 需要匹配的模组客户端</p><span class="card-link">了解科技空岛与起步指南 →</span></a></div></section><section class="portal-section" aria-labelledby="useful-guides"><p class="section-kicker">游玩时，也可以回来翻翻</p><h2 id="useful-guides">下一步要做什么？</h2><div class="portal-grid guide-grid"><a class="portal-card" href="/skyblock/getting-started.html"><span class="card-eyebrow">刚上岛</span><h3>先把家安下来</h3><p>创建岛屿、查看任务，找到第一批资源的方向。</p><span class="card-link">科技空岛新手入门 →</span></a><a class="portal-card" href="/skyblock/fishing-rewards.html"><span class="card-eyebrow">查材料</span><h3>这根鱼竿能钓到什么？</h3><p>从拾荒竿到星海竿，六级完整奖池与每次钓取的概率。</p><span class="card-link">打开漂流钓鱼奖池 →</span></a><a class="portal-card" href="/guides/"><span class="card-eyebrow">少走弯路</span><h3>随用随查的小技巧</h3><p>XPlus 设置、F3 快捷键、岛屿命令与增强生存特殊配方。</p><span class="card-link">浏览玩法知识库 →</span></a></div></section><section class="portal-section community-panel" aria-labelledby="community"><div><p class="section-kicker">一起玩，也一起琢磨</p><h2 id="community">建筑和产线，都有人愿意聊</h2><p>不在游戏里的时候，也可以通过 QQ 群和大家聊聊天，分享刚完成的建筑，或者讨论下一条生产线怎么搭。已有 QQ 群与游戏聊天互通，具体子服接入范围以群内说明为准。</p></div><div class="portal-actions"><a class="portal-button" href="https://qm.qq.com/q/qcQuFz2AwM" target="_blank" rel="noopener noreferrer">加入现有 QQ 群</a><a class="portal-text-link" href="/changelog.html">看看最近的更新 →</a></div></section>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};